"use strict";
import { useCallback, useMemo, useState } from "react";
import { useAccount } from "hooks/useAccount";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useVotedLocks } from "hooks/useVotedLocks";
import { Flex, Text } from "ui/src";
import SingleVotingRewards from "./SingleVotingRewards";
import VotingRewardsModal from "./VotingRewardsModal";
import VotingRewardsTop from "./VotingRewardsTop";
export default function VotingRewards() {
  const { address } = useAccount();
  const { data: locks = [], isLoading } = useVeABXUserLocks(address);
  const { votedLockIds, isLoading: isLoadingVotes } = useVotedLocks(locks);
  const votedLocks = locks.filter((lock) => votedLockIds.has(lock.id));
  const hasVotedLocks = votedLocks.length > 0;
  const loading = isLoading || isLoadingVotes;
  const [claimableLockIds, setClaimableLockIds] = useState({});
  const handleCanClaimStatusChange = useCallback((lockId, canClaim) => {
    setClaimableLockIds((prev) => {
      const currentlyClaimable = !!prev[lockId];
      if (canClaim === currentlyClaimable) {
        return prev;
      }
      const next = { ...prev };
      if (canClaim) {
        next[lockId] = true;
      } else {
        delete next[lockId];
      }
      return next;
    });
  }, []);
  const claimableLocks = useMemo(
    () => votedLocks.filter((lock) => claimableLockIds[lock.id]),
    [votedLocks, claimableLockIds]
  );
  const handleLockClaimed = useCallback((lockId) => {
    setClaimableLockIds((prev) => {
      if (!prev[lockId]) {
        return prev;
      }
      const next = { ...prev };
      delete next[lockId];
      return next;
    });
  }, []);
  return <Flex marginTop={"$spacing36"}>
      <VotingRewardsTop />
      
      <Flex className="locks" mt={"$spacing24"} flexDirection="column" gap={"$gap24"}>
        {loading ? (
    // Show simple loading state
    <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
    >
            <Text variant="body2" color={"$neutral2"} textAlign="center">
              Loading voting rewards...
            </Text>
          </Flex>
  ) : hasVotedLocks ? (
    // Show voting rewards for locks that have voted
    <>
            {votedLocks.map((lock) => <SingleVotingRewards
      key={lock.id}
      lock={lock}
      onCanClaimStatusChange={handleCanClaimStatusChange}
      onLockClaimed={handleLockClaimed}
    />)}
            {
      /* Show empty state if no claimable rewards after loading */
    }
            {claimableLocks.length === 0 && <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
    >
                <Text variant="body2" color={"$neutral2"} textAlign="center">
                  No voting rewards available. Vote for pools with your veABX locks to start earning rewards.
                </Text>
              </Flex>}
          </>
  ) : (
    // Show empty state when no voted locks exist
    <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
    >
            <Text variant="body2" color={"$neutral2"} textAlign="center">
              No voting rewards available. Vote for pools with your veABX locks to start earning rewards.
            </Text>
          </Flex>
  )}
      </Flex>
      
      <VotingRewardsModal />
    </Flex>;
}
