"use strict";
import { useQuery } from "@tanstack/react-query";
import { Contract } from "@ethersproject/contracts";
import { useEthersProvider } from "hooks/useEthersProvider";
import { getContract } from "utilities/src/contracts/getContract";
import { useVotingRewardsFromSubgraph } from "./useVotingRewardsFromSubgraph";
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
const MULTICALL3_ABI = [
  {
    inputs: [
      {
        components: [
          { name: "target", type: "address" },
          { name: "callData", type: "bytes" }
        ],
        name: "calls",
        type: "tuple[]"
      }
    ],
    name: "aggregate",
    outputs: [
      { name: "blockNumber", type: "uint256" },
      { name: "returnData", type: "bytes[]" }
    ],
    stateMutability: "payable",
    type: "function"
  }
];
const REWARD_CONTRACT_ABI = [
  {
    inputs: [
      { name: "token", type: "address" },
      { name: "tokenId", type: "uint256" }
    ],
    name: "earned",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
async function enhanceRewardsWithMulticall(subgraphRewards, tokenId, provider, chainId) {
  if (subgraphRewards.length === 0) {
    console.log("\u2705 [VOTING REWARDS MULTICALL] No rewards from subgraph, skipping multicall");
    return [];
  }
  const multicallContract = getContract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
  if (!multicallContract) {
    console.warn("\u26A0\uFE0F [VOTING REWARDS MULTICALL] Multicall contract not available, using subgraph amounts");
    return subgraphRewards;
  }
  const rewardInterface = new Contract(subgraphRewards[0].contractAddress, REWARD_CONTRACT_ABI).interface;
  const calls = [];
  const callMap = [];
  subgraphRewards.forEach((reward) => {
    const callIndex = calls.length;
    calls.push({
      target: reward.contractAddress,
      callData: rewardInterface.encodeFunctionData("earned", [reward.token.address, tokenId])
    });
    callMap.push({ reward, callIndex });
  });
  console.log(`\u{1F504} [VOTING REWARDS MULTICALL] Fetching ${calls.length} earned() amounts for tokenId ${tokenId}...`);
  try {
    const batchSize = 500;
    const allResults = [];
    for (let i = 0; i < calls.length; i += batchSize) {
      const batch = calls.slice(i, i + batchSize);
      const [, returnData] = await multicallContract.callStatic.aggregate(batch);
      allResults.push(...returnData);
    }
    const enhancedRewards = [];
    let totalSubgraphAmount = 0n;
    let totalOnChainAmount = 0n;
    callMap.forEach(({ reward, callIndex }) => {
      try {
        const onChainAmount = rewardInterface.decodeFunctionResult("earned", allResults[callIndex])[0];
        totalSubgraphAmount += reward.amount;
        totalOnChainAmount += BigInt(onChainAmount.toString());
        const enhancedReward = {
          ...reward,
          amount: BigInt(onChainAmount.toString())
        };
        if (enhancedReward.amount > 0n) {
          enhancedRewards.push(enhancedReward);
          const subgraphFormatted = Number(reward.amount) / 10 ** reward.token.decimals;
          const onChainFormatted = Number(enhancedReward.amount) / 10 ** reward.token.decimals;
          const percentDiff = subgraphFormatted > 0 ? Math.abs((onChainFormatted - subgraphFormatted) / subgraphFormatted * 100) : 0;
          if (percentDiff > 1) {
            console.warn(
              `\u26A0\uFE0F [VOTING REWARDS MULTICALL] Discrepancy for ${reward.token.symbol} ${reward.type}:`,
              {
                subgraph: subgraphFormatted.toFixed(6),
                onChain: onChainFormatted.toFixed(6),
                difference: `${percentDiff.toFixed(2)}%`,
                pool: `${reward.pool.token0Symbol}/${reward.pool.token1Symbol}`
              }
            );
          }
        }
      } catch (error) {
        console.warn(
          `\u26A0\uFE0F [VOTING REWARDS MULTICALL] Failed to decode earned() for ${reward.token.symbol}:`,
          error
        );
        if (reward.amount > 0n) {
          enhancedRewards.push(reward);
        }
      }
    });
    console.log(`\u2705 [VOTING REWARDS MULTICALL] Enhanced ${enhancedRewards.length}/${subgraphRewards.length} rewards`, {
      totalSubgraph: (Number(totalSubgraphAmount) / 1e18).toFixed(6),
      totalOnChain: (Number(totalOnChainAmount) / 1e18).toFixed(6)
    });
    return enhancedRewards;
  } catch (error) {
    console.error("\u274C [VOTING REWARDS MULTICALL] Multicall failed, falling back to subgraph amounts:", error);
    return subgraphRewards;
  }
}
export function useEnhanceVotingRewardsWithMulticall(lock, chainId) {
  const provider = useEthersProvider({ chainId });
  const subgraphResult = useVotingRewardsFromSubgraph(lock);
  const multicallQuery = useQuery({
    queryKey: ["enhance-voting-rewards-multicall", lock?.id, subgraphResult.rewards.length, chainId],
    queryFn: async () => {
      if (!lock?.id || !provider || !chainId || subgraphResult.rewards.length === 0) {
        return subgraphResult.rewards;
      }
      return enhanceRewardsWithMulticall(subgraphResult.rewards, lock.id, provider, chainId);
    },
    enabled: Boolean(
      lock?.id && provider && chainId && !subgraphResult.isLoading && !subgraphResult.error && subgraphResult.rewards.length > 0
    ),
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4,
    // 1 minute
    retry: 2
  });
  const isLoading = subgraphResult.isLoading || multicallQuery.isLoading && subgraphResult.rewards.length > 0;
  const finalRewards = multicallQuery.data || subgraphResult.rewards;
  return {
    ...subgraphResult,
    rewards: finalRewards,
    canClaim: finalRewards.length > 0,
    isLoading,
    refetch: async () => {
      await subgraphResult.refetch();
      await multicallQuery.refetch();
    }
  };
}
